import{_ as s,o as a,c as t,ai as n}from"./chunks/framework.ETupdKIa.js";const E=JSON.parse('{"title":"int型の範囲、オーバーフローについて","description":"","frontmatter":{"title":"int型の範囲、オーバーフローについて","date":"2026-01-06T00:00:00.000Z","status":"published"},"headers":[],"relativePath":"til/Java/20260106_int型の範囲、オーバーフローについて.md","filePath":"til/Java/20260106_int型の範囲、オーバーフローについて.md"}'),e={name:"til/Java/20260106_int型の範囲、オーバーフローについて.md"};function l(h,i,p,k,r,_){return a(),t("div",null,[...i[0]||(i[0]=[n(`<h1 id="_20260106-int型の範囲、オーバーフローについて" tabindex="-1">20260106_int型の範囲、オーバーフローについて <a class="header-anchor" href="#_20260106-int型の範囲、オーバーフローについて" aria-label="Permalink to “20260106_int型の範囲、オーバーフローについて”">​</a></h1><p>Javaのint型は符号付き32bitで表現できる範囲、すなわち-2,147,483,648~2,147,483,647が範囲である。重要な点として、int型変数がこの範囲を超える場合（オーバーフロー）に、エラーが発生しない。例えば以下のような計算結果となる。</p><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2147483647</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//int型のMAX値</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">System.out.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(b); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//-2147483648 &lt;-int型のMIN値</span></span></code></pre></div><p>計算の仕組みは2進数やら補数表現やらを理解する必要があり、別途調査することにするが、「エラーが発生しないことで、バグに気づきにくい」点を覚えておく。</p><p>金額など、絶対に間違えられない数値は、オーバーフローの可能性を考慮してlong型の利用などを検討する必要がある（Math.addExact()を使えばオーバーフロー時に例外を投げてくれるらしい）。</p>`,5)])])}const g=s(e,[["render",l]]);export{E as __pageData,g as default};
